import eventleteventlet.monkey_patch()# MediaPipe compatibility patchimport queue as _queueif not hasattr(_queue.Queue, "__class_getitem__"):    from types import GenericAlias as _GenericAlias    _queue.Queue.__class_getitem__ = classmethod(_GenericAlias)"""╔═══════════════════════════════════════════════════════════════╗║                                                               ║║   ██╗  ██╗███████╗███╗   ██╗ █████╗                          ║║   ╚██╗██╔╝██╔════╝████╗  ██║██╔══██╗                         ║║    ╚███╔╝ █████╗  ██╔██╗ ██║███████║                         ║║    ██╔██╗ ██╔══╝  ██║╚██╗██║██╔══██║                         ║║   ██╔╝ ██╗███████╗██║ ╚████║██║  ██║                         ║║   ╚═╝  ╚═╝╚══════╝╚═╝  ╚═══╝╚═╝  ╚═╝                         ║║                                                               ║║   ✦ 3D GESTURE WORKSPACE ✦                                   ║║   Professional Hand-Controlled 3D Design Platform            ║║                                                               ║╚═══════════════════════════════════════════════════════════════╝"""import osimport sysimport jsonimport base64import uuidimport loggingimport timeimport shutilfrom datetime import datetimefrom pathlib import Pathfrom io import BytesIOfrom collections import Counterimport numpy as npimport cv2import mediapipe as mpfrom flask import Flask, render_template, request, jsonify, send_file, send_from_directoryfrom flask_socketio import SocketIO, emitfrom flask_cors import CORSfrom PIL import Image# ================================================================#  1. CONFIGURATION# ================================================================HOST = '0.0.0.0'PORT = int(os.environ.get('PORT', 10000))SECRET_KEY = os.environ.get('SECRET_KEY', 'xena-super-secret-key-2026')DEBUG = os.environ.get('DEBUG', 'False').lower() == 'true'# Performance settingsMAX_FRAME_SIZE = 640 * 480FRAME_QUALITY = 60MAX_OBJECTS = 100MAX_FRAME_RATE = 30# Gesture settingsGESTURE_CONFIDENCE_THRESHOLD = 0.6SMOOTHING_FACTOR = 0.6HISTORY_SIZE = 5FRAME_SKIP = 3  # Process every 3rd frame# StorageBASE_DIR = Path(os.environ.get('BASE_DIR', '.'))UPLOAD_FOLDER = BASE_DIR / 'uploads'PROJECTS_FOLDER = UPLOAD_FOLDER / 'projects'LOGS_FOLDER = BASE_DIR / 'logs'MODELS_FOLDER = BASE_DIR / 'static' / 'models'# Create foldersUPLOAD_FOLDER.mkdir(exist_ok=True)PROJECTS_FOLDER.mkdir(exist_ok=True, parents=True)LOGS_FOLDER.mkdir(exist_ok=True)MODELS_FOLDER.mkdir(exist_ok=True, parents=True)# Logginglog_file = LOGS_FOLDER / 'xena.log'logging.basicConfig(    level=logging.DEBUG if DEBUG else logging.INFO,    format='%(asctime)s | %(levelname)s | %(message)s',    handlers=[        logging.FileHandler(log_file),        logging.StreamHandler(sys.stdout)    ])logger = logging.getLogger('XENA')# ================================================================#  2. FLASK APP SETUP# ================================================================CURRENT_DIR = Path(__file__).parent.absolute()# Smart template detectionTEMPLATES_DIR = Noneclean_templates = CURRENT_DIR / 'templates'if (clean_templates / '3d.html').exists():    TEMPLATES_DIR = clean_templatesif TEMPLATES_DIR is None:    for p in CURRENT_DIR.iterdir():        if p.is_dir() and p.name.startswith('templates') and (p / '3d.html').exists():            TEMPLATES_DIR = p            breakif TEMPLATES_DIR is None:    TEMPLATES_DIR = clean_templates    TEMPLATES_DIR.mkdir(exist_ok=True)# Smart static detectionSTATIC_DIR = Noneclean_static = CURRENT_DIR / 'static'if clean_static.exists() and clean_static.is_dir():    STATIC_DIR = clean_staticif STATIC_DIR is None:    for p in CURRENT_DIR.iterdir():        if p.is_dir() and p.name.startswith('static'):            STATIC_DIR = p            breakif STATIC_DIR is None:    STATIC_DIR = clean_static    STATIC_DIR.mkdir(exist_ok=True)app = Flask(__name__,            template_folder=str(TEMPLATES_DIR),            static_folder=str(STATIC_DIR))app.config['SECRET_KEY'] = SECRET_KEYapp.config['DEBUG'] = DEBUGapp.config['MAX_CONTENT_LENGTH'] = 50 * 1024 * 1024CORS(app, resources={r"/*": {"origins": "*"}})socketio = SocketIO(    app,    cors_allowed_origins="*",    logger=DEBUG,    engineio_logger=DEBUG,    ping_timeout=60,    ping_interval=25,    async_mode='eventlet',    manage_session=False)# ================================================================#  3. ENHANCED GESTURE RECOGNIZER# ================================================================class GestureRecognizer:    def __init__(self):        """Initialize MediaPipe Hands with enhanced features"""        self.hands = None        self.mp_hands = None        self.mp_drawing = None        self.mp_drawing_styles = None                # Performance tracking        self.frame_count = 0        self.process_count = 0        self.last_process_time = 0        self.frame_skip = FRAME_SKIP                # Gesture history for smoothing        self.gesture_history = []        self.history_size = HISTORY_SIZE        self.prev_gesture = '—'                # Confidence tracking        self.confidence_history = []        self.avg_confidence = 0.8                # Memory optimization - reuse buffers        self._frame_buffer = None        self._landmark_cache = None                # Color mapping for fingers (BGR for OpenCV)        self.finger_colors = {            'thumb': (255, 50, 50),    # Red            'index': (50, 255, 50),    # Green            'middle': (50, 50, 255),   # Blue            'ring': (255, 255, 50),    # Yellow            'pinky': (255, 50, 255)    # Purple        }                try:            self.mp_hands = mp.solutions.hands            self.mp_drawing = mp.solutions.drawing_utils            self.mp_drawing_styles = mp.solutions.drawing_styles                        self.hands = self.mp_hands.Hands(                static_image_mode=False,                max_num_hands=1,                model_complexity=1,                min_detection_confidence=0.5,                min_tracking_confidence=0.5            )                        logger.info('✅ MediaPipe initialized successfully')        except Exception as e:            logger.error(f'❌ MediaPipe initialization error: {e}')            self.hands = None        self.gesture_names = {            'fist': '✊ Fist',            'open': '🖐️ Open',            'point': '☝️ Point',            'two': '✌️ Two',            'pinch': '🤏 Pinch',            'ok': '👌 OK',            'shaka': '🤙 Shaka',            'stop': '✋ Stop',            'thumb_up': '👍 Thumb Up',            'thumb_down': '👎 Thumb Down',            'peace': '✌️ Peace',            'spock': '🖖 Spock'        }                logger.info('🖐️ GestureRecognizer initialized successfully')    def process_frame(self, image_bytes):        """Process image bytes with enhanced features"""        self.frame_count += 1                # Skip frames for performance        if self.frame_count % self.frame_skip != 0:            return None                if self.hands is None:            return None                try:            start_time = time.time()                        # Reuse buffer if possible            if self._frame_buffer is None or len(self._frame_buffer) != len(image_bytes):                self._frame_buffer = np.frombuffer(image_bytes, np.uint8)            else:                np.copyto(self._frame_buffer, np.frombuffer(image_bytes, np.uint8))                        # Decode image            image = cv2.imdecode(self._frame_buffer, cv2.IMREAD_COLOR)            if image is None:                return None                        # Convert to RGB            image_rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)            image_rgb.flags.writeable = False                        # Process with MediaPipe            results = self.hands.process(image_rgb)                        if not results.multi_hand_landmarks:                return None                        # Get landmarks            landmarks = results.multi_hand_landmarks[0]            h, w, _ = image.shape                        # Extract landmark coordinates            landmark_list = []            for lm in landmarks.landmark:                landmark_list.append({                    'x': lm.x,                    'y': lm.y,                    'z': lm.z                })                        # Calculate confidence            confidence = self._calculate_confidence(landmark_list)            self.confidence_history.append(confidence)            if len(self.confidence_history) > 10:                self.confidence_history.pop(0)            self.avg_confidence = sum(self.confidence_history) / len(self.confidence_history)                        # Skip if confidence is too low            if self.avg_confidence < GESTURE_CONFIDENCE_THRESHOLD:                return None                        # Recognize gesture            gesture = self.recognize_gesture(landmarks, landmark_list)                        # Calculate hand orientation            orientation = self.get_hand_orientation(landmark_list)                        # Calculate hand position            wrist = landmark_list[0] if landmark_list else None            hand_pos = {                'x': wrist['x'] if wrist else 0,                'y': wrist['y'] if wrist else 0,                'z': wrist['z'] if wrist else 0            }                        # Get gesture parameters            params = self.get_gesture_parameters(landmark_list, gesture)                        # Generate enhanced visualization data            viz_data = self.get_visualization_data(landmark_list, gesture, confidence)                        process_time = (time.time() - start_time) * 1000                        return {                'landmarks': landmark_list,                'gesture': gesture,                'orientation': orientation,                'position': hand_pos,                'params': params,                'confidence': self.avg_confidence,                'process_time': process_time,                'visualization': viz_data,                'timestamp': time.time()            }                    except Exception as e:            logger.error(f'Error processing frame: {e}')            return None    def _calculate_confidence(self, landmarks):        """Calculate confidence score based on landmark quality"""        if not landmarks or len(landmarks) < 21:            return 0                # Check hand geometry        wrist = landmarks[0]        index_tip = landmarks[8]        pinky_tip = landmarks[20]                # Hand width should be reasonable        hand_width = ((index_tip['x'] - pinky_tip['x']) ** 2 +                      (index_tip['y'] - pinky_tip['y']) ** 2) ** 0.5                if hand_width < 0.03 or hand_width > 0.5:            return 0.3                # Check finger lengths        finger_lengths = []        for tip_idx in [4, 8, 12, 16, 20]:            tip = landmarks[tip_idx]            mcp = landmarks[tip_idx - 2]            length = ((tip['x'] - mcp['x']) ** 2 +                      (tip['y'] - mcp['y']) ** 2) ** 0.5            finger_lengths.append(length)                avg_length = sum(finger_lengths) / len(finger_lengths)        if avg_length < 0.01 or avg_length > 0.3:            return 0.4                # Check for smoothness (z-coordinate consistency)        z_values = [lm['z'] for lm in landmarks]        z_range = max(z_values) - min(z_values)        if z_range > 0.2:            return 0.5                return 0.85  # High confidence    def recognize_gesture(self, landmarks, landmark_list):        """Enhanced gesture recognition with better accuracy"""        if not landmark_list or len(landmark_list) < 21:            return '—'                # Extract landmarks        thumb_tip = landmark_list[4]        thumb_ip = landmark_list[3]        thumb_mcp = landmark_list[2]                index_tip = landmark_list[8]        index_pip = landmark_list[6]        index_mcp = landmark_list[5]                middle_tip = landmark_list[12]        middle_pip = landmark_list[10]        middle_mcp = landmark_list[9]                ring_tip = landmark_list[16]        ring_pip = landmark_list[14]                pinky_tip = landmark_list[20]        pinky_pip = landmark_list[18]                wrist = landmark_list[0]                # Calculate finger extension with thresholds        thumb_extended = thumb_tip['y'] < thumb_ip['y'] - 0.03        index_extended = index_tip['y'] < index_pip['y'] - 0.03        middle_extended = middle_tip['y'] < middle_pip['y'] - 0.03        ring_extended = ring_tip['y'] < ring_pip['y'] - 0.03        pinky_extended = pinky_tip['y'] < pinky_pip['y'] - 0.03                # Count extended fingers        extended = [index_extended, middle_extended, ring_extended, pinky_extended]        extended_count = sum(extended)                # Thumb-index distance for pinch/ok        thumb_index_dist = ((thumb_tip['x'] - index_tip['x']) ** 2 +                           (thumb_tip['y'] - index_tip['y']) ** 2) ** 0.5                # Check gestures with priority (most specific first)        # Fist: no fingers extended        if not any(extended) and not thumb_extended:            return 'fist'                # Stop: open hand with fingers close together        if all(extended) and thumb_extended:            finger_spread = ((index_tip['x'] - pinky_tip['x']) ** 2 +                           (index_tip['y'] - pinky_tip['y']) ** 2) ** 0.5            if finger_spread < 0.15:                return 'stop'                # Open: all fingers extended and spread        if all(extended) and thumb_extended:            return 'open'                # Peace: index and middle extended, separated        if index_extended and middle_extended and not ring_extended and not pinky_extended:            finger_gap = ((index_tip['x'] - middle_tip['x']) ** 2 +                         (index_tip['y'] - middle_tip['y']) ** 2) ** 0.5            if finger_gap > 0.05:                return 'peace'            return 'two'                # Point: only index extended        if index_extended and not any([middle_extended, ring_extended, pinky_extended]):            return 'point'                # OK: thumb and index touching        if thumb_index_dist < 0.05 and not any([middle_extended, ring_extended, pinky_extended]):            return 'ok'                # Pinch: thumb and index close        if thumb_index_dist < 0.08 and index_extended:            return 'pinch'                # Shaka: thumb and pinky extended        if thumb_extended and pinky_extended and not any([index_extended, middle_extended, ring_extended]):            return 'shaka'                # Thumb up        if thumb_extended and not any(extended):            if thumb_tip['y'] < thumb_mcp['y'] - 0.02:                return 'thumb_up'            return 'thumb_down'                # Spock: index, middle, ring extended        if index_extended and middle_extended and ring_extended and not pinky_extended:            return 'spock'                return '—'    def get_hand_orientation(self, landmark_list):        """Calculate hand orientation angles"""        if not landmark_list or len(landmark_list) < 21:            return {'roll': 0, 'pitch': 0, 'yaw': 0}                wrist = landmark_list[0]        index_mcp = landmark_list[5]        pinky_mcp = landmark_list[17]        middle_mcp = landmark_list[9]                # Roll (rotation around wrist-to-middle axis)        dx = pinky_mcp['x'] - index_mcp['x']        dy = pinky_mcp['y'] - index_mcp['y']        roll = np.arctan2(dy, dx) if dx != 0 else 0                # Pitch (up/down tilt)        dx = middle_mcp['x'] - wrist['x']        dy = middle_mcp['y'] - wrist['y']        dz = middle_mcp['z'] - wrist['z']        pitch = np.arctan2(dy, np.sqrt(dx**2 + dz**2)) if (dx**2 + dz**2) > 0 else 0                # Yaw (left/right rotation)        yaw = np.arctan2(dz, dx) if dx != 0 else 0                return {            'roll': float(roll),            'pitch': float(pitch),            'yaw': float(yaw)        }    def get_gesture_parameters(self, landmark_list, gesture):        """Get additional parameters for gesture"""        params = {            'intensity': 0.5,            'value': 0.0,            'speed': 0.0        }                if not landmark_list or len(landmark_list) < 21:            return params                if gesture == 'fist':            # Fist tightness            palm_center = landmark_list[0]            tips = [landmark_list[4], landmark_list[8], landmark_list[12],                    landmark_list[16], landmark_list[20]]            distances = []            for tip in tips:                dist = ((tip['x'] - palm_center['x']) ** 2 +                       (tip['y'] - palm_center['y']) ** 2) ** 0.5                distances.append(dist)            avg_dist = np.mean(distances) if distances else 0.3            params['intensity'] = max(0, min(1, 1 - avg_dist * 3))            params['value'] = params['intensity']                    elif gesture == 'open':            # Hand spread            if len(landmark_list) > 4:                index_tip = landmark_list[8]                pinky_tip = landmark_list[20]                spread = ((index_tip['x'] - pinky_tip['x']) ** 2 +                         (index_tip['y'] - pinky_tip['y']) ** 2) ** 0.5                params['intensity'] = max(0, min(1, spread * 2))                params['value'] = params['intensity']                        elif gesture == 'pinch':            thumb_tip = landmark_list[4]            index_tip = landmark_list[8]            dist = ((thumb_tip['x'] - index_tip['x']) ** 2 +                   (thumb_tip['y'] - index_tip['y']) ** 2) ** 0.5            params['value'] = max(0, min(1, 1 - dist * 5))            params['intensity'] = params['value']                    return params    def get_visualization_data(self, landmark_list, gesture, confidence):        """Generate data for enhanced visualization"""        if not landmark_list or len(landmark_list) < 21:            return None                # Finger landmarks indices        finger_indices = {            'thumb': [1, 2, 3, 4],            'index': [5, 6, 7, 8],            'middle': [9, 10, 11, 12],            'ring': [13, 14, 15, 16],            'pinky': [17, 18, 19, 20]        }                # Get finger positions        fingers = {}        for name, indices in finger_indices.items():            fingers[name] = [landmark_list[i] for i in indices]                # Calculate center of palm        palm_points = [landmark_list[0], landmark_list[5], landmark_list[9],                        landmark_list[13], landmark_list[17]]        palm_center = {            'x': sum(p['x'] for p in palm_points) / len(palm_points),            'y': sum(p['y'] for p in palm_points) / len(palm_points),            'z': sum(p['z'] for p in palm_points) / len(palm_points)        }                return {            'fingers': fingers,            'palm_center': palm_center,            'gesture': gesture,            'confidence': confidence,            'connections': self.mp_hands.HAND_CONNECTIONS        }    def close(self):        """Clean up resources"""        if self.hands:            self.hands.close()        logger.info('🖐️ GestureRecognizer closed')# ================================================================#  4. GLOBAL INSTANCES# ================================================================gesture_recognizer = GestureRecognizer()# ================================================================#  5. FLASK ROUTES# ================================================================@app.route('/')def index():    """Serve the main application"""    try:        return render_template('3d.html')    except Exception as e:        try:            return send_from_directory(str(TEMPLATES_DIR), '3d.html')        except Exception as e2:            return f"""            <h1>XENA - Starting...</h1>            <p>If you see this, the frontend is loading.</p>            <p>Refresh the page or check the console.</p>            """, 200@app.route('/health')def health():    """Health check endpoint"""    return jsonify({        'status': 'healthy',        'timestamp': datetime.now().isoformat(),        'version': '2.0.0',        'name': 'XENA Pro',        'mediapipe_loaded': gesture_recognizer.hands is not None,        'template_exists': (TEMPLATES_DIR / '3d.html').exists(),        'active_connections': len(socketio.server.manager.rooms.get('/', {}).get('', {})) if hasattr(socketio, 'server') else 0    })@app.route('/api/save', methods=['POST'])def save_project():    """Save project to server"""    try:        data = request.json        if not data:            return jsonify({'error': 'No data provided'}), 400                project_id = data.get('id', str(uuid.uuid4()))        project_name = data.get('project', {}).get('name', 'Untitled')                data['_metadata'] = {            'saved_at': datetime.now().isoformat(),            'server_version': '2.0.0',            'id': project_id        }                filename = PROJECTS_FOLDER / f'{project_id}.xena'        with open(filename, 'w') as f:            json.dump(data, f, indent=2)                logger.info(f'💾 Project saved: {project_name} ({project_id})')                return jsonify({            'success': True,            'id': project_id,            'name': project_name,            'message': 'Project saved successfully'        })    except Exception as e:        logger.error(f'Error saving project: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/load/<project_id>', methods=['GET'])def load_project(project_id):    """Load project from server"""    try:        filename = PROJECTS_FOLDER / f'{project_id}.xena'        if not filename.exists():            return jsonify({'error': 'Project not found'}), 404                with open(filename, 'r') as f:            data = json.load(f)                logger.info(f'📂 Project loaded: {project_id}')        return jsonify(data)    except Exception as e:        logger.error(f'Error loading project: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/list_projects', methods=['GET'])def list_projects():    """List all saved projects"""    try:        projects = []        for file in PROJECTS_FOLDER.glob('*.xena'):            try:                with open(file, 'r') as f:                    data = json.load(f)                projects.append({                    'id': file.stem,                    'name': data.get('project', {}).get('name', 'Untitled'),                    'objects': len(data.get('objects', [])),                    'date': data.get('_metadata', {}).get('saved_at', 'Unknown')                })            except:                continue                projects.sort(key=lambda x: x['date'], reverse=True)        return jsonify(projects)    except Exception as e:        logger.error(f'Error listing projects: {e}')        return jsonify([])@app.route('/api/delete/<project_id>', methods=['DELETE'])def delete_project(project_id):    """Delete a project"""    try:        filename = PROJECTS_FOLDER / f'{project_id}.xena'        if not filename.exists():            return jsonify({'error': 'Project not found'}), 404                filename.unlink()        logger.info(f'🗑️ Project deleted: {project_id}')        return jsonify({'success': True, 'message': 'Project deleted'})    except Exception as e:        logger.error(f'Error deleting project: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/export/gltf', methods=['POST'])def export_gltf():    """Export project as GLTF"""    try:        data = request.json or {}        gltf_data = {            'asset': {'version': '2.0', 'generator': 'XENA v2.0.0'},            'scene': 0,            'scenes': [{'nodes': [0]}],            'nodes': [{'name': 'Exported from XENA', 'children': []}],            'meshes': [], 'materials': [], 'buffers': [],            'bufferViews': [], 'accessors': []        }                export_id = str(uuid.uuid4())        filename = PROJECTS_FOLDER / f'export_{export_id}.gltf'        with open(filename, 'w') as f:            json.dump(gltf_data, f, indent=2)                return send_file(            filename,            as_attachment=True,            download_name=f'xena_export_{export_id}.gltf',            mimetype='model/gltf+json'        )    except Exception as e:        logger.error(f'Error exporting GLTF: {e}')        return jsonify({'error': str(e)}), 500@app.route('/api/export/obj', methods=['POST'])def export_obj():    """Export project as OBJ"""    try:        data = request.json or {}        obj_content = f"# XENA Export v2.0\n# Generated: {datetime.now().isoformat()}\n\n"                export_id = str(uuid.uuid4())        filename = PROJECTS_FOLDER / f'export_{export_id}.obj'        with open(filename, 'w') as f:            f.write(obj_content)                return send_file(            filename,            as_attachment=True,            download_name=f'xena_export_{export_id}.obj',            mimetype='text/plain'        )    except Exception as e:        logger.error(f'Error exporting OBJ: {e}')        return jsonify({'error': str(e)}), 500# ================================================================#  6. WEBSOCKET EVENTS# ================================================================@socketio.on('connect')def handle_connect():    """Handle client connection"""    logger.info(f'🔗 Client connected: {request.sid}')    emit('connected', {        'message': 'Welcome to XENA Pro!',        'timestamp': datetime.now().isoformat(),        'version': '2.0.0'    })@socketio.on('disconnect')def handle_disconnect():    """Handle client disconnection"""    logger.info(f'🔌 Client disconnected: {request.sid}')@socketio.on('frame')def handle_frame(data):    """Process video frame with enhanced features"""    try:        # Handle base64 or raw bytes        if isinstance(data, str):            if data.startswith('data:image'):                data = data.split(',')[1]            image_bytes = base64.b64decode(data)        else:            image_bytes = data                # Process with gesture recognizer        result = gesture_recognizer.process_frame(image_bytes)                if result and result['landmarks']:            # Prepare response with all enhanced data            response = {                'landmarks': result['landmarks'],                'gesture': result['gesture'],                'orientation': result['orientation'],                'position': result['position'],                'params': result['params'],                'confidence': result.get('confidence', 0.8),                'process_time': result.get('process_time', 0),                'visualization': result.get('visualization', {})            }                        # Generate actions based on gesture            actions = generate_gesture_actions(result)            if actions:                response['actions'] = actions                        # Send back to client            emit('hand_landmarks', response)                except Exception as e:        logger.error(f'Error processing frame: {e}')@socketio.on('save_project')def handle_save_project(data):    """Handle save project via WebSocket"""    try:        project_id = data.get('id', str(uuid.uuid4()))        project_name = data.get('project', {}).get('name', 'Untitled')                filename = PROJECTS_FOLDER / f'{project_id}.xena'        with open(filename, 'w') as f:            json.dump(data, f, indent=2)                logger.info(f'💾 Project saved via WebSocket: {project_name} ({project_id})')                response = {            'success': True,            'id': project_id,            'name': project_name,            'message': 'Project saved successfully'        }        emit('save_response', response)        return response    except Exception as e:        logger.error(f'Error saving project via WebSocket: {e}')        response = {'success': False, 'error': str(e)}        emit('save_response', response)        return response@socketio.on('load_project')def handle_load_project(data):    """Handle load project via WebSocket"""    try:        project_id = data.get('id')        if not project_id:            response = {'error': 'No project ID provided'}            emit('load_response', response)            return response                filename = PROJECTS_FOLDER / f'{project_id}.xena'        if not filename.exists():            response = {'error': 'Project not found'}            emit('load_response', response)            return response                with open(filename, 'r') as f:            project_data = json.load(f)                logger.info(f'📂 Project loaded via WebSocket: {project_id}')        response = {'success': True, 'data': project_data}        emit('load_response', response)        return response['data']    except Exception as e:        logger.error(f'Error loading project via WebSocket: {e}')        response = {'error': str(e)}        emit('load_response', response)        return response@socketio.on('list_projects')def handle_list_projects():    """Handle list projects via WebSocket"""    try:        projects = []        for file in PROJECTS_FOLDER.glob('*.xena'):            try:                with open(file, 'r') as f:                    data = json.load(f)                projects.append({                    'id': file.stem,                    'name': data.get('project', {}).get('name', 'Untitled'),                    'objects': len(data.get('objects', [])),                    'date': data.get('_metadata', {}).get('saved_at', 'Unknown')                })            except:                continue                projects.sort(key=lambda x: x['date'], reverse=True)        emit('projects_list', projects)        return projects    except Exception as e:        logger.error(f'Error listing projects via WebSocket: {e}')        emit('projects_list', [])        return []@socketio.on('delete_project')def handle_delete_project(data):    """Handle delete project via WebSocket"""    try:        project_id = data.get('id')        if not project_id:            response = {'error': 'No project ID provided'}            emit('delete_response', response)            return response                filename = PROJECTS_FOLDER / f'{project_id}.xena'        if not filename.exists():            response = {'error': 'Project not found'}            emit('delete_response', response)            return response                filename.unlink()        logger.info(f'🗑️ Project deleted via WebSocket: {project_id}')                response = {'success': True, 'message': 'Project deleted'}        emit('delete_response', response)        return response    except Exception as e:        logger.error(f'Error deleting project via WebSocket: {e}')        response = {'error': str(e)}        emit('delete_response', response)        return response# ================================================================#  7. GESTURE ACTION GENERATOR# ================================================================def generate_gesture_actions(result):    """Generate actions based on recognized gesture"""    if not result:        return []        gesture = result['gesture']    params = result.get('params', {})    orientation = result.get('orientation', {})    position = result.get('position', {})        actions = []        # Fist: Zoom out    if gesture == 'fist':        intensity = params.get('intensity', 0.5)        actions.append({            'action': 'zoom',            'value': -intensity * 0.8,            'intensity': intensity        })        # Open: Zoom in    elif gesture == 'open':        intensity = params.get('intensity', 0.5)        actions.append({            'action': 'zoom',            'value': intensity * 0.8,            'intensity': intensity        })        # Point: Select/Hover    elif gesture == 'point':        actions.append({            'action': 'select',            'position': position        })        # Two/Peace: Drag    elif gesture in ['two', 'peace']:        actions.append({            'action': 'drag',            'dx': position.get('x', 0) * 2,            'dy': position.get('y', 0) * 2,            'dz': position.get('z', 0) * 2,            'position': position        })        # Pinch: Scale    elif gesture == 'pinch':        value = params.get('value', 0.5)        actions.append({            'action': 'scale',            'value': (value - 0.5) * 0.03,            'intensity': value        })        # OK: Properties    elif gesture == 'ok':        actions.append({            'action': 'properties',            'gesture': 'ok'        })        # Shaka: Rotate view    elif gesture == 'shaka':        roll = orientation.get('roll', 0)        pitch = orientation.get('pitch', 0)        actions.append({            'action': 'rotate',            'x': roll * 3,            'y': pitch * 3        })        # Thumb Up: Save    elif gesture == 'thumb_up':        actions.append({            'action': 'save'        })        # Thumb Down: Reset view    elif gesture == 'thumb_down':        actions.append({            'action': 'reset'        })        # Stop: Delete    elif gesture == 'stop':        actions.append({            'action': 'delete'        })        # Spock: Undo    elif gesture == 'spock':        actions.append({            'action': 'undo'        })        return actions# ================================================================#  8. MAIN ENTRY POINT# ================================================================if __name__ == '__main__':    try:        logger.info('═' * 70)        logger.info('🚀 XENA Pro Server Starting...')        logger.info(f'🌐 HTTP: http://{HOST}:{PORT}')        logger.info('═' * 70)        logger.info('📌 Press Ctrl+C to stop')        logger.info('═' * 70)                socketio.run(            app,            host=HOST,            port=PORT,            debug=DEBUG,            use_reloader=DEBUG        )    except KeyboardInterrupt:        logger.info('\n🛑 Server stopped by user')        gesture_recognizer.close()        sys.exit(0)    except Exception as e:        logger.error(f'❌ Server error: {e}')        gesture_recognizer.close()        sys.exit(1)